{
  "goal": "Deliver the one-room MVP that securely turns a RoomPlan bedroom scan into a canonical, versioned, constraint-aware scene with phone-to-web handoff, a three-pane web editor, typed conversational edits, deterministic validation, quick render, photoreal output tied to immutable scene state, single-step undo, and optional non-blocking splat preview.",
  "steps": [
    {
      "id": "step-1",
      "title": "Finalize the authoritative scene schema and semantic model",
      "description": "Before building services, do one coherent schema pass that defines all missing core types (`Polygon2D`, `RectOnSurface`, `Pose3D`, `OBB3D`, `ConstraintSpec`, `FixedElement`), separates canonical editable state from derived/cache data, and adds the semantics the later flows depend on: room-local axes and named wall references (including `north wall`), focal-element annotations, host/support relationships for anchored or fixed items, and explicit parent/child movement rules for `parent_id` and `include_children`.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-2",
      "title": "Define scene snapshots, versioning boundaries, and undo semantics",
      "description": "Define immutable scene snapshots plus a separate scene head so versioning is monotonic and unambiguous. Version only structural/material/lock state and any asset references that participate in editing, keep splat jobs, photoreal gallery entries, and other async/job metadata in sidecar records linked back to scene versions, decide whether bookmarks are sidecar or versioned metadata, and specify one-step undo as creating a new head snapshot that restores the prior editable state instead of rewinding version numbers.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-3",
      "title": "Define the secure handoff and server-authoritative API contract",
      "description": "Replace 'open the scene on a laptop with scene_id' with a concrete private access model, preferably a short-lived one-time handoff link or QR flow redeemed into an authenticated web session scoped to the scene, with no public sharing in MVP. At the same time, make the backend authoritative: keep scene-edit operations separate from dedicated command endpoints, have `/plan` return canonical ops plus a server-issued apply token or hash and idempotency data, let the client only accept or reject previewed plans rather than edit them, and define conflict/error behavior for apply, undo, photoreal, delete, and retry paths.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-4",
      "title": "Implement RoomPlan capture, ingest, and initial scene creation",
      "description": "Build the iOS capture payload and backend ingest pipeline so a RoomPlan scan plus optional video becomes the first canonical scene snapshot with stable IDs, initial derived state, and fallback `generic_obstacle` objects for unsupported detections. Persist the scene head, sidecar job records, and secure handoff artifact, and make the scene editable before any splat work finishes.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-5",
      "title": "Stand up scene reads and the initial web editor shell",
      "description": "Implement scene read and delete APIs plus the first web editor frame. Load the latest committed scene head into the three-pane UI, show the RoomPlan/scan placeholder as read-only, render the top-down shell, openings, and object footprints in the layout pane, and unify selection state so clicks in layout or render become the same entity context used by chat.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-6",
      "title": "Add asset retrieval, proxy fallback, and quick rendering",
      "description": "Ingest the curated glTF library, build deterministic asset retrieval by class, dimensions, style, and room type, and drive the live quick renderer entirely from canonical scene state rather than scan or gallery artifacts. Support proxy fallback when fit checks fail, plus orbit, selection highlight, and default or saved camera views in the render pane; if schedule slips, fall back to two defaults plus the current camera.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-7",
      "title": "Implement deterministic validation and derived-state recomputation",
      "description": "Build the simulation and derived-state pipeline in the documented order: schema, target, version, and lock checks; scene-copy simulation; hard constraints; then soft score recomputation. Use the finalized semantic model to enforce opening keep-outs, navigable paths, in-bounds and no-overlap rules, anchored or fixed support validity, class-specific access zones, wall-relative placement, focal-element scoring, and `PARENT_MOVE_VIOLATION` behavior.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-8",
      "title": "Implement atomic apply, locking, and single-step undo",
      "description": "Build the authoritative apply path for structural, material, and lock edits. Validate the expected head version and server-issued plan token, commit successful plans as new scene snapshots with recomputed derived state and operation summaries, reject stale or tampered applies with reason codes, and implement exactly one undoable commit by applying the snapshot/version rules from step 2 so non-mutating commands never enter undo history.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-9",
      "title": "Build the LLM planner and chat-driven edit workflow",
      "description": "Implement the planner and chat UX on top of the authoritative apply contract. Feed compact scene summaries, selection context, and the asset manifest into the planner, require typed edit ops only, ask clarification questions for ambiguous targets, and surface applied or rejected explanations plus machine-readable reason codes in the UI; when users ask for photoreal or undo in chat, route those intents to the dedicated command endpoints rather than modeling them as direct scene mutations.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-10",
      "title": "Ship photoreal generation, bookmarks, and version-linked gallery storage",
      "description": "Render high-resolution conditioning inputs from the committed quick-render scene, call the selected provider, and store image assets plus gallery records tied to immutable `scene_version` and camera or bookmark data. Provider failures must be isolated from scene head state, and repeated runs from the same version and view should remain structurally consistent even if style details vary.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-11",
      "title": "Add asynchronous splat jobs and scan-pane swap behavior",
      "description": "Implement optional raw-video upload and background splat processing as a non-authoritative enhancement. Attach the resulting splat as sidecar scan media when ready and let the scan pane swap from RoomPlan placeholder to splat with a clear state indicator, without changing validation or committed scene state; if time slips, keep the editor functional with placeholder-only scan views.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-12",
      "title": "Add observability, evaluation harnesses, and demo hardening",
      "description": "Instrument planner outputs, validation failures by reason code, asset misses, photoreal latency and failures, and splat job duration; build scripted room and prompt test sets for latency, invalid-edit catch rate, conversational success, structural consistency, refresh or reload stability, and deletion/privacy behavior; and use the documented cut order before sacrificing canonical versioning, typed ops, hard validation, quick render, or version-linked photoreal.",
      "requiredChecks": [
        "noop"
      ]
    }
  ]
}
